-- DOM EXTRA demo catalog import: 57 items / 19 brands.

-- IMPORTANT: prices/specs are indicative seed values, not a supplier price list. Verify before publishing.

-- Uses unique DEMO IDs/SKUs and only updates those same demo records on repeat import.

SET NAMES utf8mb4;

START TRANSACTION;

ON DUPLICATE KEY UPDATE name=VALUES(name);

ON DUPLICATE KEY UPDATE name=VALUES(name), active=1;

ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), `group_name`=VALUES(`group_name`), brand=VALUES(brand), vp_price=VALUES(vp_price), mp_price=VALUES(mp_price), long_desc=VALUES(long_desc), gallery_json=VALUES(gallery_json), specs_json=VALUES(specs_json), image=VALUES(image), stock=VALUES(stock), updated_at=NOW();

COMMIT;
